import Foundation

/// The licences of everything bundled with the app (THIRD_PARTY_NOTICES.md, generated by
/// scripts/release/generate-third-party-notices.py). The Mac and iOS apps both ship the file
/// and show it, as those licences require.
public enum ThirdPartyNotices {
    public static let fileName = "THIRD_PARTY_NOTICES.md"

    /// Reads the app's copy, or the one beside a development build's executable.
    public static func text(bundle: Bundle = .main) -> String? {
        let executableFolder = URL(fileURLWithPath: CommandLine.arguments[0]).deletingLastPathComponent()
        for folder in [bundle.resourceURL, executableFolder].compactMap({ $0 }) {
            if let data = try? Data(contentsOf: folder.appendingPathComponent(fileName)) { return String(decoding: data, as: UTF8.self) }
        }
        return nil
    }
}
